class stringx {
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
};
stringx operator+(const stringx&, const char*);
stringx operator+(const stringx&, const stringx&);
void error(const stringx&);

class script_executable { public: const stringx& get_fullname() const; };
class script_instance { public: const stringx& get_name() const; };
class script_thread {
public:
  script_instance* get_instance() const;
  script_executable* get_executable() const;
};
class vm_stack {
public:
  bool push(const char*, int);
  script_thread* get_thread() const;
};
class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY };
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t) = 0;
  };
};
class entity {
public:
  virtual ~entity();
  virtual void set_created_entity_default_active_status();
};
class beam : public entity {};
typedef beam* vm_beam_t;
class entity_maker { public: entity* acquire_beam(unsigned int); };
extern entity_maker* g_entity_maker;
enum { EFLAG_ACTIVE = 0x00200000, EFLAG_MISC_NONSTATIC = 0x08000000 };

class slf_create_beam_t : public script_library_class::function
{
public:
  virtual bool operator()( vm_stack &stack, entry_t entry )
  {
    vm_beam_t result;
    result = (vm_beam_t)g_entity_maker->acquire_beam( (unsigned int)(EFLAG_ACTIVE|EFLAG_MISC_NONSTATIC) );
    result->set_created_entity_default_active_status();
    if (!stack.push((char*)&result,sizeof(result)) )
      error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
    return true;
  }
};
